CREATE TABLE `order` (
  region VARCHAR(255) NOT NULL,
  number INT NOT NULL,
  total DECIMAL(65, 30) NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  CONSTRAINT order_pkey PRIMARY KEY (region, number)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE order_line (
  id CHAR(36) NOT NULL DEFAULT (UUID()),
  order_region VARCHAR(255) NOT NULL,
  order_number INT NOT NULL,
  sku VARCHAR(32) NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  CONSTRAINT order_line_pkey PRIMARY KEY (id),
  CONSTRAINT fk_line_order FOREIGN KEY (order_region, order_number) REFERENCES `order` (region, number) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX order_line_order_region_order_number_idx ON order_line (order_region, order_number);

CREATE TABLE tenant (
  id CHAR(36) NOT NULL DEFAULT (UUID()),
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  CONSTRAINT tenant_pkey PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE account (
  id CHAR(36) NOT NULL DEFAULT (UUID()),
  email VARCHAR(255) NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  tenant_id CHAR(36) NOT NULL,
  CONSTRAINT account_pk PRIMARY KEY (id),
  CONSTRAINT uq_account_email UNIQUE (email),
  CONSTRAINT fk_account_tenant FOREIGN KEY (tenant_id) REFERENCES tenant (id) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE profile (
  region VARCHAR(255) NOT NULL,
  number INT NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  account_id CHAR(36) NOT NULL,
  CONSTRAINT profile_pkey PRIMARY KEY (region, number),
  CONSTRAINT profile_account_id_key UNIQUE (account_id),
  CONSTRAINT profile_account_id_fkey FOREIGN KEY (account_id) REFERENCES account (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE document (
  id VARCHAR(255) NOT NULL,
  ulid VARCHAR(255) NOT NULL,
  short VARCHAR(255) NOT NULL,
  uid CHAR(36) NOT NULL DEFAULT (UUID()),
  token CHAR(36) NOT NULL DEFAULT (UUID()),
  title VARCHAR(255) NOT NULL,
  body TEXT NOT NULL,
  role ENUM('admin', 'user') NOT NULL DEFAULT 'user',
  small SMALLINT NOT NULL,
  ratio DOUBLE NOT NULL,
  price DECIMAL(10, 2) NOT NULL,
  cost DECIMAL(65, 30) NOT NULL,
  views BIGINT NOT NULL,
  `blob` LONGBLOB NOT NULL,
  meta JSON NOT NULL,
  created DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  day DATE NOT NULL,
  at TIME(6) NOT NULL,
  ip VARCHAR(45) NOT NULL,
  internal INT NOT NULL,
  legacy_name VARCHAR(255) NOT NULL,
  CONSTRAINT document_pkey PRIMARY KEY (id),
  CONSTRAINT uq_document_ulid UNIQUE (ulid)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_document_title ON document (title DESC, created) USING BTREE;
CREATE UNIQUE INDEX uq_document_title_day ON document (title, day);

CREATE TABLE scratch (
  id INT NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  CONSTRAINT scratch_pkey PRIMARY KEY (id)
